async def act(page):
    # Step 1: Extract metadata from homepage
    metadata = await extract_page_metadata(page, '/')
    main_content = metadata.get('main_content', '')

    # Step 2: Parse main_content to find posts
    # Split content into lines for processing
    lines = main_content.split('\n')
    posts = []
    current_post = {}

    for line in lines:
        line = line.strip()
        if not line:
            # Blank line might separate posts
            if current_post:
                if 'title' in current_post:
                    # Ensure we have at least a title to consider it a post
                    posts.append(current_post.copy())
                current_post = {}
            continue

        # Heuristic: assume title lines are longer and don't contain common words like 'category'
        if len(line) > 10 and 'category' not in line.lower():
            # Potential title
            current_post['title'] = line
        elif 'category' in line.lower():
            # Extract category
            parts = line.split(':', 1)
            if len(parts) > 1:
                current_post['category'] = parts[1].strip()
            else:
                current_post['category'] = line.replace('category', '').strip()

    # Add the last post if any
    if current_post and 'title' in current_post:
        posts.append(current_post.copy())

    # Step 3: Get the third-to-last post
    if len(posts) >= 3:
        target_post = posts[-3]  # third-to-last
        title = target_post.get('title', 'Not found')
        category = target_post.get('category', 'Not found')
        result = f"{title}, {category}"
    else:
        result = "Not enough posts found."

    return result

